const OPTION_DEFINITIONS = [
  { flag: '--a', dest: 'a', metavar: 'A', type: 'string', required: true },
  { flag: '--b', dest: 'b', metavar: 'B', type: 'int', required: true },
  { flag: '--c', dest: 'c', metavar: 'C', type: 'int', required: true },
];

const OPTION_BY_FLAG = new Map(
  OPTION_DEFINITIONS.map((definition) => [definition.flag, definition]),
);

function basename(pathname) {
  return pathname.split(/[\\/]/).pop() || pathname;
