function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B --c C`;
}

function helpText(prog) {
  return `${usageLine(prog)}

options:
  -h, --help  show this help message and exit
  --a A
  --b B
  --c C
`;
}

function errorText(prog, message) {
  return `${usageLine(prog)}
${prog}: error: ${message}
`;
}

function isNegativeNumberToken(token) {
  return /^-\d+(?:\.\d+)?(?:[eE][+-]?\d+)?$/.test(token);
}

function parseInteger(raw) {
  if (!/^[+-]?\d+$/.test(raw)) {
    return { ok: false };
  }

  const normalized = raw.startsWith('+') ? raw.slice(1) : raw;
  return { ok: true, value: BigInt(normalized) };
}

function parseValue(definition, raw) {
  if (definition.type === 'string') {
    return { ok: true, value: raw };
  }

  if (definition.type === 'int') {
    return parseInteger(raw);
  }

  return { ok: false };
}

function looksLikeMissingValue(token) {
  return token.startsWith('-') && !isNegativeNumberToken(token);
}

export class CliExit extends Error {
  constructor(code, stdout = '', stderr = '') {
    super(`CLI exited with code ${code}`);
    this.code = code;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

export function getProgramName(argv0 = process.argv[1] ?? 'test15.mjs') {
  return basename(argv0 || 'test15.mjs');
}

export function parseArgs(argv, prog = getProgramName()) {
  if (argv.includes('-h') || argv.includes('--help')) {
    throw new CliExit(0, helpText(prog), '');
  }

  const parsed = {};
  const unknown = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (!token.startsWith('-')) {
      unknown.push(token);
      continue;
    }

    let definition = OPTION_BY_FLAG.get(token);
    let rawValue;

    if (definition) {
      const next = argv[index + 1];

      if (next === undefined || looksLikeMissingValue(next)) {
        throw new CliExit(2, '', errorText(prog, `argument ${definition.flag}: expected one argument`));
      }

      rawValue = next;
      index += 1;
    } else {
      const separatorIndex = token.indexOf('=');

      if (separatorIndex !== -1) {
        const flag = token.slice(0, separatorIndex);
        definition = OPTION_BY_FLAG.get(flag);

        if (definition) {
          rawValue = token.slice(separatorIndex + 1);
        }
      }
    }

    if (!definition) {
      unknown.push(token);
      continue;
    }

    const parsedValue = parseValue(definition, rawValue);

    if (!parsedValue.ok) {
      throw new CliExit(
        2,
        '',
        errorText(prog, `argument ${definition.flag}: invalid int value: ${JSON.stringify(rawValue)}`),
      );
    }

    parsed[definition.dest] = parsedValue.value;
  }

  const missing = OPTION_DEFINITIONS
    .filter((definition) => definition.required && !(definition.dest in parsed))
    .map((definition) => definition.flag);

  if (missing.length > 0) {
    throw new CliExit(
      2,
      '',
      errorText(prog, `the following arguments are required: ${missing.join(', ')}`),
    );
  }

  if (unknown.length > 0) {
    throw new CliExit(2, '', errorText(prog, `unrecognized arguments: ${unknown.join(' ')}`));
  }

  return parsed;
}

