import { parseArgs, CliExit } from './lib/argv.mjs';
import { toPythonRepr } from './lib/format/python_repr.mjs';
import { toJsonRepr } from './lib/format/json_repr.mjs';
import { DeepDiff, Delta, getDiffData, getDeltaData } from './lib/deepdiff/index.mjs';

function writeStdoutLine(value) {
  process.stdout.write(`${value}\n`);
}

function renderDiff(diff) {
  return toPythonRepr(getDiffData(diff));
}

function renderDelta(delta) {
  return `<Delta: ${toJsonRepr(getDeltaData(delta))}>`;
}

function main() {
  const args = parseArgs(process.argv.slice(2));

  const obj1 = { x: args.a, y: args.b };
  const obj2 = { x: args.a, y: args.c };
  const obj3 = { x: args.a.repeat(2), y: args.b };
  const obj4 = { x: args.a, y: args.b, z: args.c };

  const diff1 = DeepDiff(obj1, obj2);
  writeStdoutLine(renderDiff(diff1));
  const delta1 = new Delta(diff1);
  writeStdoutLine(renderDelta(delta1));

  const result1 = { ...obj1 };
  Object.assign(result1, obj2);
  writeStdoutLine(toPythonRepr(result1));

  const diff2 = DeepDiff(obj1, obj3);
  writeStdoutLine(renderDiff(diff2));
  const delta2 = new Delta(diff2);
  writeStdoutLine(renderDelta(delta2));

  const diff3 = DeepDiff(obj1, obj4);
  writeStdoutLine(renderDiff(diff3));
  const delta3 = new Delta(diff3);
  writeStdoutLine(renderDelta(delta3));

  const result2 = { x: args.a.repeat(2), y: args.c };
  writeStdoutLine(toPythonRepr(result2));

  const diff4 = DeepDiff(result2, obj4);
  writeStdoutLine(renderDiff(diff4));

  const diff5 = DeepDiff(obj2, obj3);
  writeStdoutLine(renderDiff(diff5));

  const diff6 = DeepDiff(obj3, obj4);
  writeStdoutLine(renderDiff(diff6));

  const diff7 = DeepDiff(obj2, obj4);
  writeStdoutLine(renderDiff(diff7));
}

try {
  main();
} catch (error) {
  if (error instanceof CliExit) {
    if (error.stdout) {
      process.stdout.write(error.stdout);
    }

    if (error.stderr) {
      process.stderr.write(error.stderr);
    }

    process.exit(error.code);
  }

  throw error;
}

