const DIFF_DATA = Symbol('diff-data');
const DIFF_META = Symbol('diff-meta');
const DELTA_DATA = Symbol('delta-data');

function isPlainObject(value) {
  return Object.prototype.toString.call(value) === '[object Object]';
}

function cloneSnapshot(value) {
  if (Array.isArray(value)) {
    return value.map((item) => cloneSnapshot(item));
  }

  if (isPlainObject(value)) {
    const cloned = {};

    for (const [key, item] of Object.entries(value)) {
      cloned[key] = cloneSnapshot(item);
    }

    return cloned;
  }

  return value;
}

function samePrimitive(left, right) {
  return Object.is(left, right);
}

function buildObjectPath(basePath, key) {
  const escapedKey = String(key)
    .replaceAll('\\', '\\\\')
    .replaceAll("'", "\\'");

  return `${basePath}['${escapedKey}']`;
}

function compareValues(left, right, path, state) {
  if (isPlainObject(left) && isPlainObject(right)) {
    compareObjects(left, right, path, state);
    return;
  }

  if (!samePrimitive(left, right)) {
    state.valuesChanged[path] = {
      new_value: cloneSnapshot(right),
      old_value: cloneSnapshot(left),
    };
  }
}

function compareObjects(left, right, path, state) {
  const leftKeys = Object.keys(left);
  const rightKeys = Object.keys(right);

  for (const key of rightKeys) {
    if (!Object.prototype.hasOwnProperty.call(left, key)) {
      const childPath = buildObjectPath(path, key);
      state.dictionaryItemAdded.push(childPath);
      state.addedValues.set(childPath, cloneSnapshot(right[key]));
    }
  }

  for (const key of leftKeys) {
    if (!Object.prototype.hasOwnProperty.call(right, key)) {
      const childPath = buildObjectPath(path, key);
      state.dictionaryItemRemoved.push(childPath);
      state.removedValues.set(childPath, cloneSnapshot(left[key]));
    }
  }

  for (const key of leftKeys) {
    if (Object.prototype.hasOwnProperty.call(right, key)) {
      compareValues(left[key], right[key], buildObjectPath(path, key), state);
    }
  }
}

function buildDiffData(state) {
  const data = {};

  if (state.dictionaryItemAdded.length > 0) {
    data.dictionary_item_added = state.dictionaryItemAdded;
  }

  if (state.dictionaryItemRemoved.length > 0) {
    data.dictionary_item_removed = state.dictionaryItemRemoved;
  }

  if (Object.keys(state.valuesChanged).length > 0) {
    data.values_changed = state.valuesChanged;
  }

  return data;
}

export class DeepDiffResult {
  constructor(data, meta) {
    this[DIFF_DATA] = data;
    this[DIFF_META] = meta;
  }
}

export function DeepDiff(left, right) {
  const state = {
    dictionaryItemAdded: [],
    dictionaryItemRemoved: [],
    valuesChanged: {},
    addedValues: new Map(),
    removedValues: new Map(),
  };

  compareValues(left, right, 'root', state);

  return new DeepDiffResult(buildDiffData(state), {
    addedValues: state.addedValues,
    removedValues: state.removedValues,
  });
}

export class Delta {
  constructor(diff) {
    const diffData = getDiffData(diff);
    const meta = diff instanceof DeepDiffResult ? diff[DIFF_META] : {
      addedValues: new Map(),
      removedValues: new Map(),
    };
    const deltaData = {};

    if (Array.isArray(diffData.dictionary_item_added) && diffData.dictionary_item_added.length > 0) {
      const added = {};

      for (const path of diffData.dictionary_item_added) {
        added[path] = cloneSnapshot(meta.addedValues.get(path));
      }

      deltaData.dictionary_item_added = added;
    }

    if (Array.isArray(diffData.dictionary_item_removed) && diffData.dictionary_item_removed.length > 0) {
      const removed = {};

      for (const path of diffData.dictionary_item_removed) {
        removed[path] = cloneSnapshot(meta.removedValues.get(path));
      }

      deltaData.dictionary_item_removed = removed;
    }

    if (diffData.values_changed) {
      const valuesChanged = {};

      for (const [path, change] of Object.entries(diffData.values_changed)) {
        valuesChanged[path] = {
          new_value: cloneSnapshot(change.new_value),
        };
      }

      if (Object.keys(valuesChanged).length > 0) {
        deltaData.values_changed = valuesChanged;
      }
    }

    this[DELTA_DATA] = deltaData;
  }
}

export function getDiffData(diff) {
  return diff instanceof DeepDiffResult ? diff[DIFF_DATA] : diff;
}

export function getDeltaData(delta) {
  return delta instanceof Delta ? delta[DELTA_DATA] : delta;
}

