  if (typeof value === 'string') {
    return pythonStringRepr(value);
  }

  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new TypeError('Only finite numbers are supported.');
    }

    return Object.is(value, -0) ? '0' : String(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (value === null) {
    return 'None';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => pythonRepr(item)).join(', ')}]`;
  }

  if (typeof value === 'object') {
    const entries = Object.keys(value).map((key) => `${pythonStringRepr(key)}: ${pythonRepr(value[key])}`);
    return `{${entries.join(', ')}}`;
  }

