  if (isPlainObject(left) && isPlainObject(right)) {
    compareObjects(left, right, path, state);
    return;
  }

  if (!Object.is(left, right)) {
    state.valuesChanged[path] = {
      new_value: cloneSnapshot(right),
      old_value: cloneSnapshot(left),
    };
  }
